issue_context.body:
### Describe the bug

SWC generates faulty code when using `module.lazy = true` and `module.type = "commonjs"` along with nested closures.

It will generate a mix of lazy and non-lazy code:

```js
import { spawn } from "child_process";

function log() {
  console.log(spawn);
}

const other = () => {
  const nestedClosure = () => {
    spawn("ls");
  };
};
```

Generates 

```js
"use strict";
var _childProcess = require("child_process");
function log() {
    console.log(_childProcess().spawn);
}
const other = ()=>{
    const nestedClosure = ()=>{
        (0, _childProcess).spawn("ls");
    };
};
```

Notice that the `require` statement and the call in `nestedClosure` are non-lazy, but the call in `function log()` is `lazy`.

## Ways to not get the problem

### Inverting the functions

Inverting the order of the `log` and `other` functions will not produce the same issue. Instead, `swc` will generate completely non-lazy, but functional code.

```js
import { spawn } from "child_process";

const other = () => {
  const nestedClosure = () => {
    spawn("ls");
  };
};

function log() {
  console.log(spawn);
}
```

Generates

```js
"use strict";
var _childProcess = require("child_process");
const other = ()=>{
    const nestedClosure = ()=>{
        (0, _childProcess).spawn("ls");
    };
};
function log() {
    console.log(_childProcess.spawn);
}
```

### Avoid using nested closures

Replacing either `other` or `nestedClosure` with a named function will also produce valid, lazy code:

```js
import { spawn } from "child_process";

function log() {
  console.log(spawn);
}

function other() {
  const nestedClosure = () => {
    spawn("ls");
  };
};
```

Generates

```js
"use strict";
function _childProcess() {
    const data = require("child_process");
    _childProcess = function() {
        return data;
    };
    return data;
}
function log() {
    console.log(_childProcess().spawn);
}
function other() {
    const nestedClosure = ()=>{
        _childProcess().spawn("ls");
    };
}
```

### Input code

```typescript
import { spawn } from "child_process";

function log() {
  console.log(spawn);
}

const other = () => {
  const nestedClosure = () => {
    spawn("ls");
  };
};
```


### Config

```json
{
  "jsc": {
    "parser": {
      "syntax": "typescript"
    },
    "target": "es2020"
  },
  "module": {
    "type": "commonjs",
    "lazy": true
  }
}
```


### Playground link

https://play.swc.rs/?version=1.2.115&code=H4sIAAAAAAAAA1WOMQrDMBAE%2B3vFospu8gHhNHlICPI5Fsg6oTuTwujvkRMIpN2dHTZuRarhgJbHK6NhqbLBhTWm%2BV6qBFZ1nmjZc7AoGUmew4iDgCBZJfHlTD7r0VMjOmOD2MoVEzo7XX%2B4IbMaz7ckulf%2B6%2FG9MLikrpuA1nWe3kTS5YKhAAAA&config=H4sIAAAAAAAAA0WNSQ6DMAxF7%2BI1iypL7tBDWKlBQWSQbaSmEXevg4LY2X94v8EmHuYGBVmI%2ByU1KX5hBq2FxHMoChOomLTgLnTag7ySWoTEvZwze89ZaAQmiCGFpXaYz7EwiTwWpnW%2Fk6exYv4cXWjXnjGtEnPapFPxZxTlo4%2Fe0AEK8h7Ny%2F8DWryisckAAAA%3D

### Expected behavior

I expect the output to produce a lazy `require` statement, along with lazy `_childProcess()` calls.

```js
"use strict";
function _childProcess() {
    const data = require("child_process");
    _childProcess = function() {
        return data;
    };
    return data;
}
function log() {
    console.log(_childProcess().spawn);
}
const other = ()=>{
    const nestedClosure = () => {
        _childProcess().spawn("ls");
    }
};
```

### Version

@swc/cli: 0.1.55, @swc/core: 1.2.121

