```js
import { fn, Klass } from "other-lib";

function myFn() {
    fn()
};

class MyClass extends Klass {}
```

Generates

```js
"use strict";
var _otherLib = require("other-lib");
function myFn() {
    _otherLib().fn();
}
class MyClass extends _otherLib.Klass {
}

```

